// go: github.com/microsoft/typescript-go/internal/ls.classificationForSymbol cdbade58
fun classificationForSymbol(symbol: Symbol?): ClassificationTypeName {
    if (symbol == null) {
        return ClassificationTypeName("text")
    }
    val flags: SymbolFlags = symbol!!.flags
    when {
        flags.value and 3u != 0u -> {
            if (isFirstDeclarationOfSymbolParameter(symbol)) {
                return ClassificationTypeName("parameter name")
            }
            return ClassificationTypeName("local name")
        }
        flags.value and 4u != 0u -> {
            return ClassificationTypeName("property name")
        }
        flags.value and 32768u != 0u -> {
            return ClassificationTypeName("property name")
        }
        flags.value and 65536u != 0u -> {
            return ClassificationTypeName("property name")
        }
        flags.value and 8u != 0u -> {
            return ClassificationTypeName("field name")
        }
        flags.value and 16u != 0u -> {
            return ClassificationTypeName("method name")
        }
        flags.value and 32u != 0u -> {
            return ClassificationTypeName("class name")
        }
        flags.value and 64u != 0u -> {
            return ClassificationTypeName("interface name")
        }
        flags.value and 384u != 0u -> {
            return ClassificationTypeName("enum name")
        }
        flags.value and 1536u != 0u -> {
            return ClassificationTypeName("module name")
        }
        flags.value and 8192u != 0u -> {
            return ClassificationTypeName("method name")
        }
        flags.value and 262144u != 0u -> {
            return ClassificationTypeName("type parameter name")
        }
        flags.value and 524288u != 0u -> {
            return ClassificationTypeName("identifier")
        }
        flags.value and 2097152u != 0u -> {
            return ClassificationTypeName("identifier")
        }
        else -> {
            return ClassificationTypeName("text")
        }
    }
    goUnreachable()
}

// go: github.com/microsoft/typescript-go/internal/ls.isFirstDeclarationOfSymbolParameter 7d77764b
fun isFirstDeclarationOfSymbolParameter(symbol: Symbol?): Boolean {
    val declarations: GoSlice<Node?> = symbol!!.declarations
    if (declarations.len == 0) {
        return false
    }
    return declarations[0]!!.kind.value == 170
}


